insert into public.reviews (name, location, rating, body, item) select 'Patricia L.', 'Makati City', 5, 'Item was exactly as described — even better in person. Fast replies on Messenger and very careful packaging. Will definitely buy again!', 'Chanel Classic Flap' where not exists (select 1 from public.reviews where name = 'Patricia L.' and body = 'Item was exactly as described — even better in person. Fast replies on Messenger and very careful packaging. Will definitely buy again!');
insert into public.reviews (name, location, rating, body, item) select 'Miguel R.', 'Cebu City', 5, 'First time buying a pre-loved watch online and I was nervous, but they sent extra photos and a video of the movement. Arrived in Cebu in 2 days.', 'Rolex Datejust' where not exists (select 1 from public.reviews where name = 'Miguel R.' and body = 'First time buying a pre-loved watch online and I was nervous, but they sent extra photos and a video of the movement. Arrived in Cebu in 2 days.');
insert into public.reviews (name, location, rating, body, item) select 'Andrea S.', 'Quezon City', 5, 'Used their layaway and it was so easy to track my balance. Super legit and accommodating. Thank you HIGHLUX!', 'LV Neverfull MM' where not exists (select 1 from public.reviews where name = 'Andrea S.' and body = 'Used their layaway and it was so easy to track my balance. Super legit and accommodating. Thank you HIGHLUX!');
insert into public.reviews (name, location, rating, body, item) select 'Joanna T.', 'Davao City', 5, 'Authentic with complete inclusions. Paid via GCash, shipped the same day. Highly recommended seller.', 'Tiffany T Bracelet' where not exists (select 1 from public.reviews where name = 'Joanna T.' and body = 'Authentic with complete inclusions. Paid via GCash, shipped the same day. Highly recommended seller.');
insert into public.site_settings (key, value) values ('home', '{"heroImageUrl":"/placeholders/hero.svg","heroEyebrow":"Authentic Luxury, Timeless Investment.","heroHeadline":"Pre-Loved Luxury Bags","heroSubline":"Bags | Watches | Diamonds | Jewelry","heroScript":"Your Next Luxury Awaits.","heroCtaLabel":"Shop Now","heroCtaHref":"/shop"}'::jsonb) on conflict (key) do nothing;
